"""Pure, offline Daraja helpers: formatting, signing and payload parsing.

Nothing here performs network I/O, so it is safe to call from tests, skill
scripts and MCP tools alike.
"""

from __future__ import annotations

import base64
import re
from datetime import datetime, timedelta, timezone
from typing import Any

# Daraja timestamps are interpreted in East Africa Time (UTC+3, no DST).
EAT = timezone(timedelta(hours=3), "EAT")

_PHONE_RE = re.compile(r"^(?:\+?254|0)?([17]\d{8})$")


def normalize_phone(raw: str | int) -> str:
    """Return a phone number in Daraja's 2547XXXXXXXX / 2541XXXXXXXX form.

    Accepts 07..., 01..., 7..., +2547..., 2547... with spaces or dashes.
    Raises ValueError for anything that is not a Kenyan mobile number.
    """
    digits = re.sub(r"[\s\-()]", "", str(raw))
    match = _PHONE_RE.match(digits)
    if not match:
        raise ValueError(
            f"Invalid Kenyan mobile number {raw!r}; expected e.g. 0712345678 or 254712345678"
        )
    return "254" + match.group(1)


def timestamp(now: datetime | None = None) -> str:
    """YYYYMMDDHHmmss in EAT, as required by STK Push and Ratiba."""
    now = now or datetime.now(EAT)
    return now.astimezone(EAT).strftime("%Y%m%d%H%M%S")


def stk_password(shortcode: str | int, passkey: str, ts: str) -> str:
    """base64(BusinessShortCode + Passkey + Timestamp)."""
    return base64.b64encode(f"{shortcode}{passkey}{ts}".encode()).decode()


def basic_auth_header(consumer_key: str, consumer_secret: str) -> str:
    token = base64.b64encode(f"{consumer_key}:{consumer_secret}".encode()).decode()
    return f"Basic {token}"


def validate_amount(amount: int | float | str, minimum: int = 1) -> int:
    """Daraja only accepts whole shillings."""
    value = float(amount)
    if value != int(value):
        raise ValueError(f"Amount must be a whole number of shillings, got {amount!r}")
    if value < minimum:
        raise ValueError(f"Amount must be at least {minimum}, got {amount!r}")
    return int(value)


def security_credential(initiator_password: str, cert_pem_or_der: bytes) -> str:
    """RSA PKCS#1 v1.5 encrypt the initiator password with Safaricom's cert.

    Use SandboxCertificate.cer for sandbox and ProductionCertificate.cer for
    production. The output differs on every call (random padding); that is
    expected.
    """
    from cryptography import x509
    from cryptography.hazmat.primitives.asymmetric import padding

    try:
        cert = x509.load_pem_x509_certificate(cert_pem_or_der)
    except ValueError:
        cert = x509.load_der_x509_certificate(cert_pem_or_der)
    encrypted = cert.public_key().encrypt(initiator_password.encode(), padding.PKCS1v15())
    return base64.b64encode(encrypted).decode()


